def resultingStringAfterAdjacentRemovals(s: str) -> str:
    stack = []
    for c in s:
        # Check if stack is not empty and top is consecutive with current char (circular: 'a' and 'z' too)
        if stack and abs(ord(stack[-1]) - ord(c)) in (1, 25):
            stack.pop()  # Remove the consecutive pair
        else:
            stack.append(c)  # Otherwise, add to stack
    # Join the stack to get the resulting string
    return ''.join(stack)
